<template>
  <AppLayout page-title="Ordonnances">
    <div class="card" v-for="r in items" :key="r.id"><div class="flex items-center justify-between"><div><b>{{ r.prescription_code }}</b><div>Dr. {{ r.doctor?.first_name }} {{ r.doctor?.last_name }}</div></div><span class="badge badge-green">{{ r.status }}</span></div><p>{{ r.general_instructions || 'Aucune instruction générale.' }}</p><ul><li v-for="i in r.prescription_items" :key="i.id"><b>{{ i.medication_name }}</b> — {{ i.form }} {{ i.dosage }}, {{ i.quantity }} unité(s), {{ i.frequency }} pendant {{ i.duration_days }} jours</li></ul><div class="pharmacy-transfer"><h3>Transférer à une pharmacie</h3><select class="input" v-model="selectedPharmacy[r.id]"><option value="">Choisir une pharmacie</option><option v-for="ph in pharmacies" :key="ph.id" :value="ph.id">{{ ph.name }} — {{ ph.city }}</option></select><input class="input" v-model="notes[r.id]" placeholder="Note pour la pharmacie (facultatif)"><button class="btn btn-primary" :disabled="!selectedPharmacy[r.id] || sending===r.id" @click="transfer(r)">{{ sending===r.id ? 'Transmission…' : 'Transmettre à la pharmacie' }}</button><small v-if="messages[r.id]" class="success">{{ messages[r.id] }}</small></div><div v-if="r.transfers?.length" class="transfer-status"><div v-for="t in r.transfers" :key="t.id">{{ t.pharmacy?.name }} — <b>{{ t.status }}</b></div></div></div>
    <div v-if="loading" class="loading-overlay"><div class="spinner"/></div><div v-if="!loading && !items.length" class="empty-state"><div class="empty-icon">💊</div><div>Aucune ordonnance.</div></div>
  </AppLayout>
</template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';const auth=useAuthStore(),items=ref<any[]>([]),pharmacies=ref<any[]>([]),loading=ref(true),sending=ref<string|null>(null),selectedPharmacy=ref<Record<string,string>>({}),notes=ref<Record<string,string>>({}),messages=ref<Record<string,string>>({});async function load(){if(!auth.user)return;loading.value=true;const [rx,ph]=await Promise.all([supabase.from('prescriptions').select('*,doctor:profiles!prescriptions_doctor_id_fkey(first_name,last_name),prescription_items(*),transfers:prescription_pharmacy_transfers(id,status,pharmacy_id,pharmacy:pharmacies(id,name,city))').eq('patient_id',auth.user.id).order('created_at',{ascending:false}),supabase.from('pharmacies').select('id,name,city').eq('is_active',true).eq('is_verified',true).order('name')]);items.value=rx.data||[];pharmacies.value=ph.data||[];loading.value=false}async function transfer(r:any){if(!auth.user||!selectedPharmacy.value[r.id])return;sending.value=r.id;messages.value[r.id]='';const active=(r.transfers||[]).find((t:any)=>['pending','accepted','dispensing'].includes(t.status)&&t.pharmacy_id===selectedPharmacy.value[r.id]);if(active){messages.value[r.id]='Cette ordonnance est déjà en cours de traitement par cette pharmacie.';sending.value=null;return}const {error}=await supabase.from('prescription_pharmacy_transfers').insert({prescription_id:r.id,patient_id:auth.user.id,pharmacy_id:selectedPharmacy.value[r.id],patient_notes:notes.value[r.id]||null});messages.value[r.id]=error?error.message:'Ordonnance transmise à la pharmacie.';if(!error)await load();sending.value=null}onMounted(load)</script>
